from flask import Blueprint, render_template, request, redirect, url_for
from app.models.note import Note
from app.database import db

notes_bp = Blueprint('notes', __name__, template_folder='templates')

@notes_bp.route('/', methods=['GET'])
def index():
    notes = Note.query.all()
    return render_template('index.html', notes=notes)

@notes_bp.route('/add', methods=['POST'])
def add_note():
    note_content = request.form.get('content')
    if note_content:
        new_note = Note(content=note_content)
        db.session.add(new_note)
        db.session.commit()
    return redirect(url_for('notes.index'))

@notes_bp.route('/delete/<int:note_id>', methods=['POST'])
def delete_note(note_id):
    note = Note.query.get(note_id)
    if note:
        db.session.delete(note)
        db.session.commit()
    return redirect(url_for('notes.index'))

/* static/styles.css */
/* General styling for the Note-Taking App */

/* Reset some default styles */
body, h1, h2, h3, p, ul, ol, li, button, input {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

/* Body styling */
body {
  font-family: Arial, sans-serif;
  background-color: #f4f4f9;
  color: #333;
  line-height: 1.6;
  padding: 20px;
}

/* Header styling */
header {
  background-color: #6200ea;
  color: white;
  padding: 10px 20px;
  text-align: center;
  border-radius: 8px;
  margin-bottom: 20px;
}

header h1 {
  font-size: 1.8rem;
}

/* Container for content */
.container {
  max-width: 600px;
  margin: 0 auto;
  padding: 20px;
  background: white;
  border-radius: 8px;
  box-shadow: 0 4px 6px rgba(0, 0, 0, 0.1);
}

/* Form styling */
form {
  margin-bottom: 20px;
}

form input[type="text"] {
  width: 100%;
  padding: 10px;
  margin-bottom: 10px;
  border: 1px solid #ccc;
  border-radius: 4px;
}

form button {
  background-color: #6200ea;
  color: white;
  border: none;
  padding: 10px 15px;
  border-radius: 4px;
  cursor: pointer;
}

form button:hover {
  background-color: #4500b0;
}

/* Notes list styling */
.notes {
  list-style-type: none;
}

.notes li {
  background: #f4f4f9;
  border: 1px solid #ddd;
  border-radius: 4px;
  padding: 10px;
  margin-bottom: 10px;
}

.notes li:hover {
  background: #e0e0f8;
}

